cypher:
// First, find the user with the lowest reputation
MATCH (u:User)
WITH u
ORDER BY u.reputation ASC
LIMIT 1

// Then, find all questions asked by this user
MATCH (u)-[:ASKED]->(q:Question)

// Finally, find all tags for these questions
MATCH (q)-[:TAGGED]->(t:Tag)
RETURN DISTINCT t.name AS tag

MATCH (o:Organization)-[:IN_CITY]->(c:City)-[:IN_COUNTRY]->(co:Country)
WHERE o.nbrEmployees > 10000 AND NOT EXISTS {
    MATCH (capital:City)-[:IN_COUNTRY {capital: true}]->(co)
    WHERE c = capital
}
RETURN o.name AS OrganizationName, o.nbrEmployees AS NumberOfEmployees, c.name AS CityName, co.name AS CountryName

MATCH (org:Organization)-[:IN_CITY]->(city:City)-[:IN_COUNTRY]->(country:Country)
WHERE NOT EXISTS {
  MATCH (capital:City)-[:IN_COUNTRY {capital: true}]->(country)
  WHERE city = capital
}
RETURN org.name AS organizationName, city.name AS cityName, country.name AS countryName

MATCH (o:Organization)
WHERE EXISTS {
    MATCH (o)-[:HAS_INVESTOR]->(:Person)
    UNION
    MATCH (o)-[:HAS_INVESTOR]->(:Organization)
}
AND NOT EXISTS {
    MATCH (o)-[:HAS_SUBSIDIARY]->(:Organization)
}
RETURN o.name

MATCH (org:Organization)-[:HAS_CEO]->(ceo:Person)
WHERE org.revenue > 1.0E9 AND EXISTS {
    MATCH (org)-[:HAS_SUBSIDIARY]->(:Organization)
}
RETURN ceo.name AS CEO_Name, org.name AS Organization_Name
LIMIT 3

MATCH (org:Organization)-[:IN_CITY]->(city:City)-[:IN_COUNTRY]->(country:Country)
WHERE NOT EXISTS {
    MATCH (capitalCity:City)-[:IN_COUNTRY {isCapital: true}]->(country)
    WHERE city = capitalCity
}
RETURN org.name AS organizationName, city.name AS cityName, country.name AS countryName

// First, find the minimum amount in the database
MATCH (f:Filing)
WITH min(f.amount) AS minAmount

// Then, find the filings with that minimum amount
MATCH (f:Filing {amount: minAmount})
RETURN f

MATCH (e:Entity)
WHERE NOT EXISTS {
  MATCH (e)<-[:BENEFITS]-(:Filing)
}
RETURN count(e) AS numberOfEntities

// Step 1: Find all businesses in Missoula
MATCH (b:Business {city: 'Missoula'})-[:REVIEWS]-(r:Review)

// Step 2: Collect the stars for each business
WITH b, collect(r.stars) as stars, collect(r.text) as review_texts

// Step 3: Calculate the range of stars for each business
WITH b, review_texts, apoc.coll.max(stars) - apoc.coll.min(stars) as star_range

// Step 4: Find the business with the maximum range of stars
ORDER BY star_range DESC
LIMIT 1

// Step 5: Return the business name and review texts
RETURN b.name as business_name, review_texts

MATCH (c:Category)<-[:IN_CATEGORY]-(b:Business)
WHERE NOT EXISTS {
  MATCH (b)<-[:REVIEWS]-(r:Review)
  WHERE r.text CONTAINS 'awesome'
}
RETURN c.name AS CategoryWithoutAwesomeReviews

MATCH (b:Business)
WHERE NOT EXISTS {
  MATCH (b)<-[:REVIEWS]-(:Review)
}
RETURN b.name

// First, find the location of the business at '301 E Main St'
MATCH (b:Business {address: '301 E Main St'})
WITH b.location AS referenceLocation

// Then, find all businesses within 1km of the reference location
MATCH (nearbyBusiness:Business)
WHERE distance(nearbyBusiness.location, referenceLocation) <= 1000

// Return the names and addresses of these businesses
RETURN nearbyBusiness.name AS businessName, nearbyBusiness.address AS businessAddress

MATCH (p:Person)-[:PRODUCED]->(m:Movie)
WHERE NOT EXISTS {
  MATCH (p)-[:ACTED_IN]->(:Movie)
}
RETURN p.name AS Producer

MATCH (m:Movie)<-[:REVIEWED]-(p:Person)
WHERE EXISTS {
  MATCH (p)-[r:REVIEWED]->(m)
  WHERE r.rating = 75
}
RETURN m.title

MATCH (m:Movie)<-[:REVIEWED]-(p:Person)
WHERE EXISTS {
  MATCH (p)-[r:REVIEWED]->(m)
  WHERE r.summary = 'Fun, but a little far fetched'
}
RETURN m.title

MATCH (p:Person)-[:PRODUCED]->(m:Movie)
WHERE NOT EXISTS {
  MATCH (p)-[:DIRECTED]->(:Movie)
}
RETURN p.name
LIMIT 3

MATCH (director:Person)-[:DIRECTED]->(movie:Movie)
WHERE NOT EXISTS {
  MATCH (director)-[:REVIEWED]->(:Movie)
}
RETURN director.name
LIMIT 3

MATCH (m:Movie)<-[:REVIEWED]-(p:Person)
WHERE EXISTS {
  MATCH (p)-[r:REVIEWED]->(m)
  WHERE r.summary = 'Dark, but compelling'
}
RETURN m.title

MATCH (director:Person)-[:CREW_FOR]->(adult:Adult {status: 'Released'}),
      (director)-[:CREW_FOR]->(video:Video {status: 'Released'})
WHERE EXISTS {
  MATCH (director)-[:CREW_FOR]->(adult)-[:IN_GENRE]->(:Genre {name: 'Adult'})
}
AND EXISTS {
  MATCH (director)-[:CREW_FOR]->(video)-[:IN_GENRE]->(:Genre {name: 'Video'})
}
AND (director)-[:CREW_FOR]->(:Adult)-[:IN_GENRE]->(:Genre {name: 'Adult'})
AND (director)-[:CREW_FOR]->(:Video)-[:IN_GENRE]->(:Genre {name: 'Video'})
RETURN DISTINCT director.name
LIMIT 3

MATCH (p:Person)-[:CREW_FOR]->(m:Movie), 
      (p)-[:CREW_FOR]->(a:Adult)
WHERE EXISTS {
  MATCH (p)-[:CREW_FOR {job: "Director"}]->(m)
} AND EXISTS {
  MATCH (p)-[:CREW_FOR {job: "Director"}]->(a)
}
RETURN DISTINCT p.name
LIMIT 3

// Step 1: Find the product with the highest unit price
MATCH (p:Product)
WITH p
ORDER BY p.unitPrice DESC
LIMIT 1

// Step 2: Find the orders for this product
MATCH (p)<-[:ORDERS]-(o:Order)

// Step 3: Find the customers who placed these orders
MATCH (c:Customer)-[:PURCHASED]->(o)

// Step 4: Count the number of orders per customer and get the top 5 customers
WITH c, COUNT(o) AS orderCount
ORDER BY orderCount DESC
LIMIT 5

// Step 5: Return the top 5 customers
RETURN c.companyName AS customerName, orderCount

// Step 1: Calculate the average unit price of all products
MATCH (p:Product)
WITH avg(p.unitPrice) AS avgUnitPrice

// Step 2: Find products with a unit price less than the average unit price
MATCH (p:Product)
WHERE p.unitPrice < avgUnitPrice

// Step 3: Return the first 5 products that meet the criteria
RETURN p.productName, p.unitPrice
ORDER BY p.unitPrice
LIMIT 5

MATCH (a:Actor)-[:ACTED_IN]->(m:Movie)
WHERE NOT EXISTS {
  MATCH (a)-[:ACTED_IN]->(m2:Movie)
  WHERE m2.year > 2010
}
RETURN a.name

MATCH (u:User)-[r:RATED]->(m:Movie)
WHERE NOT EXISTS {
    MATCH (u)-[:RATED]->(m2:Movie)-[:IN_GENRE]->(g:Genre {name: 'Sci-Fi'})
}
RETURN DISTINCT u.name

MATCH (a:Actor)
WHERE NOT EXISTS {
  MATCH (a)-[:ACTED_IN]->(m:Movie)-[:IN_GENRE]->(g:Genre {name: 'Action'})
}
RETURN a.name

// Define the current timestamp and the timestamp for one year ago
WITH timestamp() AS current_time, timestamp() - 31536000 AS one_year_ago

// Match users who have asked questions in the last year
MATCH (u:User)-[:ASKED]->(q:Question)
WHERE q.creation_date >= one_year_ago

// Count the number of questions each user has asked
WITH u, COUNT(q) AS question_count

// Order by the number of questions in descending order and limit to the top users
ORDER BY question_count DESC
LIMIT 10

// Return the users and their question counts
RETURN u.display_name AS user, question_count

// Step 1: Find the top 3 most viewed questions
MATCH (q:Question)
WITH q
ORDER BY q.view_count DESC
LIMIT 3

// Step 2: Find the accepted answers for these questions
MATCH (q)<-[:ANSWERED]-(a:Answer)
WHERE a.is_accepted = true

// Step 3: Find the users who provided these accepted answers
MATCH (u:User)-[:PROVIDED]->(a)

// Step 4: Return the users' display names and the corresponding question titles
RETURN u.display_name AS user, q.title AS question_title

// Step 1: Find the stream with the most followers
MATCH (s:Stream)
WITH s
ORDER BY s.followers DESC
LIMIT 1

// Step 2: Find users who are chatters in this stream
MATCH (s)-[:CHATTER]->(u:User)

// Step 3: Find the streams where these users are chatters
MATCH (u)-[:CHATTER]->(otherStream:Stream)

// Step 4: Return the streams
RETURN DISTINCT otherStream
